-- Tình huống (phần 3)
INSERT INTO public.scenarios (category_id, title, title_zh, description, situation, learning_objectives, difficulty, estimated_minutes, ai_role, ai_role_zh, ai_personality, initial_message, suggested_phrases, is_published)
SELECT c.id, s.title, s.title_zh, s.description, s.situation, s.obj, s.diff, s.mins, s.ai_role, s.ai_role_zh, s.pers, s.init, s.phr::jsonb, TRUE
FROM (VALUES
($q$Logistics - Kho vận$q$, $q$Báo cáo tiến độ nhập hàng ca sáng với Quản lý$q$, $q$向经理汇报早班入库进度$q$, $q$Bạn báo cáo tình hình nhập kho ca sáng và giải thích lý do một lô hàng bị chậm cho sếp trực tiếp.$q$, $q$Bạn đang làm việc tại kho hàng của công ty. Quản lý người Trung Quốc bước đến và hỏi về tiến độ xử lý các container hàng nhập khẩu sáng nay, trong đó có một lô hàng bị rách bao bì cần kiểm tra lại.$q$, ARRAY[$q$Sử dụng từ vựng cơ bản về kho vận và nhập hàng$q$,$q$Biết cách báo cáo số liệu và tiến độ công việc đơn giản$q$,$q$Cách giải thích ngắn gọn khi gặp sự cố nhỏ$q$]::text[], $q$beginner$q$, 10, $q$Quản lý kho người Trung Quốc$q$, $q$中国仓库经理$q$, $q$Nhiệt tình nhưng bận rộn, nói tiếng Trung rõ ràng, tốc độ vừa phải.$q$, $q$小李，早上的集装箱卸货卸完了吗？有没有什么异常情况？$q$, $q$[{"zh":"早上的集装箱已经卸完了一半。","vi":"Container buổi sáng đã dỡ xong một nửa rồi."},{"zh":"这箱货物的包装有点破损，正在核对数量。","vi":"Lô hàng này bao bì hơi hỏng một chút, đang đối chiếu số lượng."},{"zh":"预计下午两点前能全部完成入库。","vi":"Dự kiến trước 2 giờ chiều là có thể hoàn thành nhập kho tất cả."},{"zh":"请经理放心，我会尽快处理好。","vi":"Xin quản lý cứ yên tâm, tôi sẽ xử lý xong sớm nhất có thể."}]$q$),
($q$Logistics - Kho vận$q$, $q$Xử lý khiếu nại sai sót đơn hàng với khách hàng$q$, $q$处理客户订单差错投诉$q$, $q$Bạn tiếp nhận cuộc gọi từ khách hàng phàn nàn về việc giao thiếu hàng và đưa ra hướng giải quyết.$q$, $q$Điện thoại bộ phận dịch vụ khách hàng vang lên. Một khách hàng đại lý gọi đến với thái độ không hài lòng vì đơn hàng nhận được thiếu 5 kiện hàng so với chứng từ.$q$, ARRAY[$q$Kỹ năng lắng nghe và xoa dịu khách hàng bất mãn$q$,$q$Sử dụng từ vựng chuyên ngành về đơn hàng, phiếu xuất kho, khiếu nại$q$,$q$Đưa ra cam kết kiểm tra và thời hạn phản hồi cụ thể$q$]::text[], $q$intermediate$q$, 15, $q$Đại diện khách hàng khó tính$q$, $q$挑剔的客户代表$q$, $q$Nóng tính, yêu cầu giải quyết nhanh, nói nhanh với từ ngữ thương mại.$q$, $q$喂？你们怎么回事？我们今天收到的货少了五个箱子，生产线都快停了！$q$, $q$[{"zh":"非常抱歉给您带来了不便，我 马上帮您查一下原因。","vi":"Rất xin lỗi vì đã gây bất tiện cho quý khách, tôi sẽ giúp anh/chị kiểm tra nguyên nhân ngay."},{"zh":"请您提供一下订单号和出库单的编号。","vi":"Xin anh/chị cung cấp mã đơn hàng và số phiếu xuất kho."},{"zh":"如果确实是我们仓库漏发了，今天之内我们会 安排补发。","vi":"Nếu đúng là kho chúng tôi giao sót, trong hôm nay chúng tôi sẽ sắp xếp gửi bù."},{"zh":"处理结果出来后，我会在半小时内给您回电。","vi":"Sau khi có kết quả xử lý, tôi sẽ gọi lại cho anh/chị trong vòng nửa tiếng."}]$q$),
($q$Logistics - Kho vận$q$, $q$Thương lượng thời gian giao hàng cao điểm với Công ty vận tải$q$, $q$与运输公司协商高峰期配送时间$q$, $q$Bạn làm việc với đối tác vận chuyển để đẩy nhanh tiến độ giao hàng trong mùa cao điểm.$q$, $q$Đang là mùa mua sắm cao điểm, lượng hàng tồn kho đọng lại nhiều. Bạn gọi điện cho công ty đối tác vận tải phụ trách tuyến đường phía Nam để yêu cầu họ tăng thêm xe tải.$q$, ARRAY[$q$Sử dụng từ vựng thương lượng và hợp đồng vận chuyển nâng cao$q$,$q$Kỹ năng thuyết phục đối tác ưu tiên nguồn lực trong thời điểm căng thẳng$q$,$q$Cách chốt thời gian và điều kiện cam kết bằng tiếng Trung$q$]::text[], $q$advanced$q$, 20, $q$Giám đốc vận tải của đối tác$q$, $q$物流供应商运输总监$q$, $q$Thực tế, khôn ngoan, hay viện lý do thiếu xe và tài xế để từ chối tăng chuyến.$q$, $q$张经理，不是我们不帮忙，现在仓库车辆 实在 C 紧张，司机也都在连轴转啊。$q$, $q$[{"zh":"我理解贵司的难处，但这次这批货真的很紧急，客户催得很紧。","vi":"Tôi hiểu khó khăn của quý công ty, nhưng lô hàng lần này thực sự rất gấp, khách hàng giục rất dữ."},{"zh":"能不能从其他 unassigned 的线路调两辆车过来支援一下？","vi":"Có thể điều động hai xe từ các tuyến chưa phân công sang hỗ trợ một chút được không?"},{"zh":"如果能在明天上午10点前送达，我们可以 考虑增加百分之十的加急费。","vi":"Nếu có thể giao hàng trước 10 giờ sáng mai, chúng tôi có thể cân nhắc tăng 10% phí hỏa tốc."},{"zh":"那就这么说定了，麻烦您帮我落实一下具体的车牌号和司机电话。","vi":"Vậy quyết định thế nhé, phiền anh giúp tôi chốt lại biển số xe cụ thể và số điện thoại tài xế."}]$q$),
($q$Logistics - Kho vận$q$, $q$Kiểm kê kho định kỳ cùng đồng nghiệp ca đêm$q$, $q$与夜班同事进行定期库存盘点$q$, $q$Bạn phối hợp với một đồng nghiệp người Trung Quốc để kiểm tra số lượng thực tế và đối chiếu hệ thống WMS.$q$, $q$Đã đến giờ giao ca tối. Bạn cùng đồng nghiệp phụ trách khu vực kệ hàng điện tử thực hiện kiểm kê thực tế (Stocktake) để tìm ra nguyên nhân lệch kho nhỏ.$q$, ARRAY[$q$Giao tiếp công việc nội bộ tự nhiên, chuyên nghiệp với đồng nghiệp bản xứ$q$,$q$Sử dụng thuật ngữ WMS (Hệ thống quản lý kho), mã SKU, vị trí kệ hàng$q$,$q$Cách xác nhận và ghi nhận sai lệch kiểm kê$q$]::text[], $q$intermediate$q$, 15, $q$Đồng nghiệp ca đêm người Trung Quốc$q$, $q$中国夜班仓库同事$q$, $q$Thân thiện, chăm chỉ, nói chuyện tự nhiên bằng tiếng lóng công nghiệp nhẹ.$q$, $q$哎，小陈，这边B区3号货架的电子配件系统数据显示还有50个，但我们数了只有48个，你来看看怎么回事？$q$, $q$[{"zh":"系统里的SKU编号和实物标签对得上吗？","vi":"Mã SKU trong hệ thống và nhãn hàng thực tế có khớp nhau không?"},{"zh":"会不会是昨天出库的时候漏扫码了？","vi":"Có phải hôm qua lúc xuất kho bị sót mã quét không nhỉ?"},{"zh":"我们再去 adjacent 的几个货架找找看有没有放错位置。","vi":"Chúng ta qua mấy kệ hàng lân cận tìm thử xem có bị đặt nhầm vị trí không."},{"zh":"找不到的话，先在盘点表上做个标记，等会儿向主管汇报。","vi":"Nếu không tìm thấy, cứ đánh dấu vào bảng kiểm kê trước, lát nữa báo cáo quản lý."}]$q$),
($q$Logistics - Kho vận$q$, $q$Phối hợp giải quyết hàng hóa hư hỏng với bộ phận Kiểm soát chất lượng$q$, $q$与质检部门协调处理货损问题$q$, $q$Bạn trao đổi với nhân viên QC để lập biên bản và xử lý lô hàng nhập kho bị móp méo bao bì.$q$, $q$Bạn đang kiểm tra hàng nhập kho từ nhà cung cấp thì phát hiện một pallet sữa bị rách bao bì và chảy nước. Bạn cần gọi điện hoặc trực tiếp gặp nhân viên QC nội bộ để yêu cầu họ xuống xác nhận tình trạng hàng hóa và lập biên bản xử lý.$q$, ARRAY[$q$Biết cách báo cáo sự cố hàng hóa bằng tiếng Trung trong nội bộ công ty$q$,$q$Sử dụng từ vựng chuyên ngành về tình trạng hư hỏng (hư hỏng, rách bao bì, chảy nước)$q$,$q$Đề xuất hướng giải quyết tiếp theo với bộ phận kiểm định$q$]::text[], $q$beginner$q$, 15, $q$Nhân viên Kiểm soát chất lượng (QC)$q$, $q$质检员$q$, $q$Làm việc nguyên tắc, cẩn trọng nhưng cởi mở hỗ trợ thực tập sinh.$q$, $q$喂， A栋仓库的货损吗？我手头有点忙，大概十分钟后过去看，是什么情况？$q$, $q$[{"zh":"这箱货物的包装破损了，里面有漏液。","vi":"Thùng hàng này bị rách bao bì, bên trong có hiện tượng rò rỉ chất lỏng."},{"zh":"麻烦您过来帮我确认一下并拍个照记录。","vi":"Làm phiền bạn qua giúp mình xác nhận và chụp ảnh ghi lại."},{"zh":"我们需要出一份货损报告吗？","vi":"Chúng ta có cần lập một báo cáo hàng hóa hư hỏng không?"},{"zh":"这个批次的货暂时先隔离存放吧。","vi":"Lô hàng này tạm thời cứ cách ly lưu kho đã nhé."}]$q$),
($q$Logistics - Kho vận$q$, $q$Giải thích quy trình xuất kho chậm với khách hàng doanh nghiệp$q$, $q$向企业客户解释出库延迟原因$q$, $q$Bạn gọi điện giải thích lý do hệ thống WMS gặp trục trặc khiến xe tải của khách đến nhận hàng bị chậm.$q$, $q$Đại diện khách hàng doanh nghiệp đang chờ lấy hàng tại cửa kho số 3 nhưng hệ thống quản lý kho (WMS) đột ngột bị lỗi kết nối khiến việc quét mã xuất kho bị đình trệ 30 phút. Bạn cần gọi điện giải thích tình hình và xoa dịu sự khó chịu của họ.$q$, ARRAY[$q$Rèn luyện kỹ năng giao tiếp xử lý khủng hoảng với khách hàng bên ngoài$q$,$q$Sử dụng các mẫu câu xin lỗi và trấn an lịch sự trong tiếng Trung thương mại$q$,$q$Diễn đạt rõ ràng nguyên nhân kỹ thuật khách quan và thời gian dự kiến khắc phục$q$]::text[], $q$intermediate$q$, 18, $q$Đại diện công ty khách hàng$q$, $q$客户代表$q$, $q$Nóng tính, coi trọng thời gian và chi phí vận chuyển.$q$, $q$喂？我们派来的车已经在3号月台等了半个小时了，怎么还没装好货？司机说你们系统出问题了，到底什么时候能好？$q$, $q$[{"zh":"非常抱歉，由于我们的系统刚才出现了一点故障...","vi":"Rất xin lỗi, do hệ thống của chúng tôi vừa rồi gặp chút trục trặc..."},{"zh":"技术人员正在全力修复，预计15分钟内恢复正常。","vi":"Nhân viên kỹ thuật đang nỗ lực khắc phục, dự kiến sẽ khôi phục bình thường trong 15 phút tới."},{"zh":"感谢您的耐心等待，我们会优先为您安排装车。","vi":"Cảm ơn sự kiên nhẫn của quý khách, chúng tôi sẽ ưu tiên sắp xếp bốc hàng cho anh/chị."},{"zh":"如果给贵公司带来不便，我们深表歉意。","vi":"Nếu gây ra bất tiện cho quý công ty, chúng tôi xin bày tỏ sự cáo lỗi sâu sắc."}]$q$),
($q$Logistics - Kho vận$q$, $q$Thảo luận tối ưu hóa vị trí lưu kho (Slotting) với Trưởng phòng Logistics$q$, $q$与物流经理讨论仓库货位优化$q$, $q$Bạn trình bày đề xuất sắp xếp lại sơ đồ kệ hàng để giảm thời gian di chuyển cho nhân viên nhặt hàng.$q$, $q$Trong buổi họp tuần của bộ phận kho, Quản lý yêu cầu các nhân viên và thực tập sinh đưa ra ý kiến cải tiến hiệu suất vận hành. Bạn đã chuẩn bị số liệu và muốn đề xuất thay đổi vị trí các mặt hàng bán chạy (fast-moving items) ra gần cửa xuất hàng hơn.$q$, ARRAY[$q$Phát triển kỹ năng thuyết trình, đề xuất ý kiến với cấp trên bằng tiếng Trung chuyên ngành$q$,$q$Sử dụng từ vựng nâng cao về quản trị kho vận (tối ưu hóa, luân chuyển hàng hóa, hiệu suất)$q$,$q$Biết cách bảo vệ quan điểm bằng số liệu thực tế$q$]::text[], $q$advanced$q$, 20, $q$Trưởng phòng Logistics công ty$q$, $q$物流经理$q$, $q$Sắc sảo, thực tế, luôn đánh giá cao các giải pháp dựa trên số liệu và hiệu quả chi phí.$q$, $q$小张，你刚才说对拣货动线有优化建议？具体说说看，这能帮我们节省多少时间？$q$, $q$[{"zh":"根据最近一个月的出库数据分析，我发现...","vi":"Dựa trên phân tích dữ liệu xuất kho trong một tháng qua, tôi nhận thấy..."},{"zh":"建议把高频出货的商品调整到靠近月台的货架。","vi":"Đề xuất điều chỉnh các mặt hàng xuất kho tần suất cao về phía kệ gần cửa xuất hàng."},{"zh":"这样可以缩短拣货员百分之三十的步行距离。","vi":"Như vậy có thể rút ngắn 30% quãng đường đi bộ của nhân viên nhặt hàng."},{"zh":"这是一个初步的方案，请您审阅并提出宝贵意见。","vi":"Đây là phương án sơ bộ, kính mong anh/chị xem xét và đóng góp ý kiến quý báu."}]$q$),
($q$Logistics - Kho vận$q$, $q$Phối hợp với đối tác hãng tàu quốc tế về việc dời lịch container$q$, $q$与国际船运代理协调集装箱船期变更$q$, $q$Bạn làm việc với nhân viên hãng tàu để cập nhật lại thời gian cắt máng (Closing time) cho container hàng xuất khẩu.$q$, $q$Do tắc nghẽn giao thông đường bộ, xe container chở lô hàng xuất khẩu của công ty dự kiến đến cảng muộn hơn thời gian cắt máng (Closing time) 2 tiếng. Bạn phải liên hệ khẩn cấp với nhân viên điều phối của hãng tàu đối tác để xin gia hạn hoặc dời sang chuyến sau.$q$, ARRAY[$q$Nắm vững thuật ngữ tiếng Trung về xuất nhập khẩu và vận tải biển (cắt máng, container, booking)$q$,$q$Rèn luyện kỹ năng thương lượng khẩn cấp trong tình huống ngoại giao với đối tác$q$,$q$Biết cách đưa ra cam kết thời gian và chịu trách nhiệm xử lý chứng từ$q$]::text[], $q$advanced$q$, 20, $q$Nhân viên điều phối hãng tàu / Đại lý Forwarder$q$, $q$船务代理协调员$q$, $q$Khắt khe về thời gian, tuân thủ nghiêm ngặt quy định hải quan và hãng tàu.$q$, $q$这里是XX船务代理。你们这票货的截关时间（Closing time）马上就到了，拖车怎么还没进港？$q$, $q$[{"zh":"由于路况突发拥堵，拖车预计会延迟两小时到达。","vi":"Do tình hình giao thông ùn tắc bất ngờ, xe đầu kéo dự kiến sẽ đến muộn hai tiếng."},{"zh":"请问能否帮我们向码头申请延时截关半小时？","vi":"Xin hỏi có thể giúp chúng tôi xin cảng gia hạn thời gian cắt máng thêm nửa tiếng được không?"},{"zh":"如果赶不上这班船，改签下一个航次的费用怎么算？","vi":"Nếu không kịp chuyến tàu này, chi phí đổi sang chuyến tiếp theo tính thế nào?"},{"zh":"我们愿意承担因此产生的相关文档更改费。","vi":"Chúng tôi sẵn sàng chịu chi phí sửa đổi chứng từ liên quan phát sinh do việc này."}]$q$),
($q$Giáo dục - Đào tạo$q$, $q$Nhận bàn giao công việc từ đồng nghiệp cũ$q$, $q$与老员工交接工作$q$, $q$Làm quen với quy trình soạn thảo giáo案 và bàn giao công việc nội bộ trong ngày đầu đi làm.$q$, $q$Bạn là thực tập sinh mới tại trung tâm giáo dục. Hôm nay, một đồng nghiệp người Trung Quốc sẽ hướng dẫn bạn cách sử dụng hệ thống quản lý học viên và bàn giao tài liệu giảng dạy.$q$, ARRAY[$q$Hiểu thuật ngữ cơ bản về giáo dục$q$,$q$Biết cách đặt câu hỏi làm rõ nhiệm vụ$q$,$q$Thể hiện thái độ ham học hỏi$q$]::text[], $q$beginner$q$, 10, $q$Đồng nghiệp hướng dẫn người Trung Quốc$q$, $q$带教同事$q$, $q$Nhiệt tình, chu đáo và kiên nhẫn.$q$, $q$你好！欢迎来到我们培训中心。我是负责带你的同事，今天我先带你熟悉一下我们的教务系统和备课流程吧。$q$, $q$[{"zh":"请问这个系统怎么操作？","vi":"Xin hỏi hệ thống này thao tác thế nào?"},{"zh":"这个教案有什么特别的要求吗？","vi":"Giáo án này có yêu cầu gì đặc biệt không?"},{"zh":"我记下来了，谢谢你。","vi":"Tôi đã ghi lại rồi, cảm ơn bạn."},{"zh":"我还有一点不太明白。","vi":"Tôi vẫn còn một chút chưa hiểu lắm."}]$q$),
($q$Giáo dục - Đào tạo$q$, $q$Tư vấn khóa học cho phụ huynh học sinh$q$, $q$向学生家长咨询课程$q$, $q$Giao tiếp với khách hàng là phụ huynh để giới thiệu chương trình học tiếng Trung.$q$, $q$Bạn đang trực tại quầy lễ tân của trung tâm. Một phụ huynh đến tìm hiểu về khóa học tiếng Trung cho con và hỏi về lộ trình học tập, học phí.$q$, ARRAY[$q$Nắm vững kỹ năng tư vấn dịch vụ giáo dục$q$,$q$Sử dụng từ vựng về khóa học, học phí$q$,$q$Biết cách xử lý thắc mắc của khách hàng$q$]::text[], $q$intermediate$q$, 15, $q$Phụ huynh học sinh$q$, $q$学员家长$q$, $q$Quan tâm đến chất lượng học tập và cân nhắc về giá cả.$q$, $q$老师您好，我想了解一下你们这里的少儿汉语课程，不知道学费是怎么收的？授课老师都是外教吗？$q$, $q$[{"zh":"请让我为您介绍一下我们的课程设置。","vi":"Xin phép để tôi giới thiệu cho anh/chị về cơ cấu khóa học của chúng tôi."},{"zh":"我们的课程包含听说读写全方位培养。","vi":"Khóa học của chúng tôi bao gồm bồi dưỡng toàn diện nghe nói đọc viết."},{"zh":"现在报名还有优惠活动。","vi":"Bây giờ đăng ký vẫn có chương trình ưu đãi."},{"zh":"如果您有任何疑问，随时可以问我。","vi":"Nếu anh/chị có bất kỳ thắc mắc nào, có thể hỏi tôi bất cứ lúc nào."}]$q$),
($q$Giáo dục - Đào tạo$q$, $q$Họp bàn về phương án hợp tác giáo dục với đối tác$q$, $q$商讨教育合作方案$q$, $q$Tham gia cuộc họp với đối tác trường học nước ngoài để bàn về chương trình trao đổi học sinh.$q$, $q$Bạn là trợ lý dự án trong buổi họp trực tuyến với đại diện một trường tiểu học tại Trung Quốc. Bạn cần ghi chép và đưa ra ý kiến đóng góp ngắn gọn về lịch trình giao lưu.$q$, ARRAY[$q$Sử dụng ngôn ngữ thương mại và giáo dục trang trọng$q$,$q$Kỹ năng trình bày ý kiến trong cuộc họp$q$,$q$Biết cách ghi nhận và phản hồi ý kiến đối tác$q$]::text[], $q$advanced$q$, 20, $q$Đại diện đối tác giáo dục$q$, $q$合作方代表$q$, $q$Chuyên nghiệp, coi trọng hiệu quả và chi tiết.$q$, $q$各位好，关于这次两校夏令营的日程安排，我们希望在文化体验环节增加一些互动课程，贵方觉得如何？$q$, $q$[{"zh":"关于这个方案，我们团队有以下几点建议。","vi":"Về phương án này, đội ngũ chúng tôi có mấy điểm góp ý sau đây."},{"zh":"我们非常赞同贵方的提议。","vi":"Chúng tôi rất đồng tình với đề xuất của quý công ty."},{"zh":"考虑到时间成本，我们建议适当调整一下。","vi":"Cân nhắc đến chi phí thời gian, chúng tôi đề nghị điều chỉnh lại một chút."},{"zh":"会后我们会把详细的纪要发给大家。","vi":"Sau cuộc họp, chúng tôi sẽ gửi biên bản chi tiết cho mọi người."}]$q$),
($q$Giáo dục - Đào tạo$q$, $q$Báo cáo tiến độ dự án đổi mới giáo dục với sếp$q$, $q$向领导汇报教改项目进度$q$, $q$Trình bày báo cáo công việc và xin ý kiến chỉ đạo từ quản lý trực tiếp.$q$, $q$Bạn có cuộc họp 1-1 với giám đốc đào tạo để báo cáo kết quả thử nghiệm chương trình học trực tuyến mới và đề xuất hướng giải quyết cho một số vấn đề phát sinh.$q$, ARRAY[$q$Kỹ năng báo cáo công việc chuyên nghiệp$q$,$q$Biết cách nêu vấn đề và đề xuất giải pháp$q$,$q$Lắng nghe và tiếp thu phản hồi từ cấp trên$q$]::text[], $q$advanced$q$, 15, $q$Giám đốc đào tạo$q$, $q$教务总监$q$, $q$Nghiêm túc, yêu cầu cao về tiến độ và chất lượng.$q$, $q$小陈，上周让你跟进的在线课程测试情况怎么样了？学生和老师们的反馈如何？$q$, $q$[{"zh":"向您汇报一下目前的整体进展。","vi":"Tôi xin báo cáo với sếp về tiến độ tổng thể hiện tại."},{"zh":"测试结果显示，大部分学员对此很满意。","vi":"Kết quả kiểm tra cho thấy, phần lớn học viên rất hài lòng với việc này."},{"zh":"不过，我们也遇到了一些技术上的小问题。","vi":"Tuy nhiên, chúng tôi cũng gặp một số vấn đề nhỏ về kỹ thuật."},{"zh":"针对这个问题，我们拟定了两个解决方案。","vi":"Đối với vấn đề này, chúng tôi đã vạch ra hai phương án giải quyết."}]$q$),
($q$Giáo dục - Đào tạo$q$, $q$Phối hợp giáo viên chủ nhiệm xử lý học sinh mất trật tự$q$, $q$协助班主任处理课堂纪律$q$, $q$Bạn trao đổi với giáo viên chủ nhiệm người Trung Quốc để tìm cách hỗ trợ một học viên hay làm việc riêng trong lớp học tiếng Trung.$q$, $q$Bạn là giáo viên trợ giảng người Việt tại một trung tâm ngoại ngữ. Sau giờ học, bạn đến văn phòng gặp giáo viên chủ nhiệm lớp để phản ánh tình hình học tập và phối hợp xử lý thái độ mất trật tự của một học viên.$q$, ARRAY[$q$Biết cách báo cáo tình hình lớp học bằng tiếng Trung cơ bản$q$,$q$Sử dụng từ vựng về quản lý lớp học và hành vi học sinh$q$,$q$Hiểu cách trao đổi lịch sự, mang tính xây dựng với đồng nghiệp lớn tuổi hơn$q$]::text[], $q$beginner$q$, 12, $q$Giáo viên chủ nhiệm người Trung Quốc$q$, $q$中国班主任$q$, $q$Thân thiện, nhiệt tình nhưng hơi bận rộn và coi trọng kỷ luật lớp học.$q$, $q$老师，你来得正好。我刚听助教说这节课后排的几个学生不太安 听讲，具体情况是怎样的？$q$, $q$[{"zh":"老师，我想跟您反映一下今天课堂上的情况。","vi":"Thầy/Cô ơi, em muốn phản ánh với thầy/cô về tình hình trong lớp học hôm nay ạ."},{"zh":"这个学生上课的时候经常玩手机。","vi":"Học sinh này trong giờ học thường xuyên chơi điện thoại."},{"zh":"您看我们应该怎么提醒他比较合适？","vi":"Thầy/Cô thấy chúng ta nên nhắc nhở bạn ấy thế nào cho phù hợp ạ?"},{"zh":"谢谢您的建议，我明天会特别注意。","vi":"Cảm ơn góp ý của thầy/cô, ngày mai em sẽ đặc biệt chú ý."}]$q$),
($q$Giáo dục - Đào tạo$q$, $q$Giải quyết khiếu nại hoàn học phí của học viên$q$, $q$处理学员退费投诉$q$, $q$Bạn đối thoại với một phụ huynh đang rất bức xúc và yêu cầu hoàn lại học phí khóa học trực tuyến.$q$, $q$Bạn làm việc tại bộ phận dịch vụ khách hàng của một công ty EdTech. Một phụ huynh gọi điện đến phàn nàn rằng con họ không thích ứng được với lịch học trực tuyến mới và kiên quyết đòi rút tiền học phí còn lại.$q$, ARRAY[$q$Thành thạo kỹ năng xoa dịu khách hàng đang tức giận bằng tiếng Trung$q$,$q$Nắm vững các mẫu câu giải thích quy định hoàn tiền của công ty một cách khéo léo$q$,$q$Biết cách đưa ra giải pháp thay thế để giữ chân khách hàng$q$]::text[], $q$intermediate$q$, 15, $q$Phụ huynh học sinh đang bức xúc$q$, $q$愤怒的家长$q$, $q$Nóng tính, nói nhanh, đòi quyền lợi tối đa và không dễ chấp nhận lời giải thích chung chung.$q$, $q$你们这儿怎么回事儿？网课质量不好不说，现在我想退课，你们客服推三阻四的到底什么意思？$q$, $q$[{"zh":"家长您先别生气，请您慢慢说，我一定帮您妥善解决。","vi":"Phụ huynh cứ bình tĩnh, xin hãy nói từ từ, tôi nhất định sẽ giúp anh/chị giải quyết ổn thỏa."},{"zh":"我非常理解您的心情和对孩子学习的担忧。","vi":"Tôi rất hiểu tâm trạng và sự lo lắng của anh/chị đối với việc học của con."},{"zh":"按照公司的规定，课程进行到这个阶段可以按比例进行退费。","vi":"Theo quy định của công ty, khóa học đến giai đoạn này có thể hoàn tiền theo tỷ lệ."},{"zh":"如果您愿意，我们可以帮您把剩余课时转到更适合的周末班。","vi":"Nếu anh/chị đồng ý, chúng tôi có thể giúp anh/chị chuyển số buổi còn lại sang lớp cuối tuần phù hợp hơn."}]$q$),
($q$Giáo dục - Đào tạo$q$, $q$Tranh luận điều khoản hợp đồng nhượng quyền giáo dục$q$, $q$洽谈教育加盟合同条款$q$, $q$Bạn đại diện công ty đàm phán các điều khoản về tỷ lệ chia sẻ doanh thu với đối tác nhượng quyền.$q$, $q$Bạn tham gia buổi họp đàm phán với đại diện một trường tư thục tại tỉnh khác muốn mua bản quyền chương trình STEM của công ty bạn. Đối tác đang yêu cầu giảm tỷ lệ hoa hồng chiết khấu.$q$, ARRAY[$q$Sử dụng từ vựng kinh doanh và giáo dục nâng cao trong đàm phán$q$,$q$Biết cách bảo vệ lợi ích công ty mà vẫn giữ quan hệ tốt với đối tác$q$,$q$Thành thạo cấu trúc câu nhượng binh, thuyết phục và chốt vấn đề$q$]::text[], $q$advanced$q$, 18, $q$Đại diện đối tác nhượng quyền$q$, $q$加盟合作方代表$q$, $q$Cứng rắn, sắc sảo, tính toán kỹ lưỡng về mặt tài chính và hay ép giá.$q$, $q$王经理，贵司提出的百分之三十的利润分成比例实在太高了。考虑到我们前期投入的推广成本，必须得重新商量。$q$, $q$[{"zh":"非常感谢贵方对我们课程体系的认可和诚意。","vi":"Rất cảm ơn sự công nhận và thành ý của quý công ty đối với hệ thống khóa học của chúng tôi."},{"zh":"这个分成比例是基于我们多年研发的高品质内容和强大的师资支持。","vi":"Tỷ lệ chia sẻ này dựa trên nội dung chất lượng cao và sự hỗ trợ đội ngũ giáo viên hùng hậu mà chúng tôi nghiên cứu phát triển nhiều năm."},{"zh":"如果在首年合作期内，我们可以考虑在其他方面给贵方一定的政策倾斜。","vi":"Nếu trong thời hạn hợp tác năm đầu tiên, chúng tôi có thể cân nhắc dành cho quý vị một số chính sách ưu đãi ở các mặt khác."},{"zh":"希望我们能在互利共赢的基础上达成最终的协议。","vi":"Hy vọng chúng ta có thể đạt được thỏa thuận cuối cùng trên cơ sở đôi bên cùng có lợi."}]$q$),
